  (() => {
    // Kandidaten vom Analyze-Node – nimm was befüllt ist
    const raw =($json['0'].content[0].text).trim();

    // Fallback: sinnvoller Titel, falls nichts da
    const fallback = `Image ${$json.id || ''}`.trim();

    if (!raw) return fallback;

    // erste Satzhälfte nehmen
    let first = (raw.split(/[.!?\n]/).find(s => s && s.trim().length) || raw).trim();

    // leading Phrasen weg
    first = first
      .replace(/^\s*(the|this)\s+image\s+(shows|depicts|displays)\s*/i, '')
      .replace(/^\s*(an?\s+|the\s+)?(photo|image)\s+of\s+/i, '')
      .trim();

 first = first
      .replace(/^\s*(Auf dem|Das)\s+Bild\s+(sieht man|zeigt)\s*/i, '')
      .replace(/^\s*(einen?\s+|ein\s+)?(Bild)\s+of\s+/i, '')
      .trim();

    // auf 10 Wörter kürzen
    const words = first.split(/\s+/);
    let title = words.slice(0, 10).join(' ');

    // Erstes Zeichen groß
    title = title.charAt(0).toUpperCase() + title.slice(1);

    return title || fallback;
  })()
}}

