// 🧠 Safe conversion of session summary text to binary for Google Drive upload
const store = $getWorkflowStaticData('global');
if (!store.sessionSummaryFiles || typeof store.sessionSummaryFiles !== 'object') {
  store.sessionSummaryFiles = {};
}

// 🔹 Get session info
const sessionItems = $items('Set Session Vars', 0, 0);
const sessionId = sessionItems[0]?.json?.sessionId || 'unknown-session';

// 🔹 Skip if we already uploaded a summary for this session
if (store.sessionSummaryFiles[sessionId]) {
  console.log(`✅ Session ${sessionId} summary already uploaded (file ${store.sessionSummaryFiles[sessionId]}). Skipping re-upload.`);
  return [];
}

// 🔹 Extract summary text from API response (robustly handle all cases)
let raw = $json.data ?? $json.body ?? $json.text ?? $json.mediaSummary ?? '';
if (typeof raw !== 'string') {
  try {
    raw = JSON.stringify(raw, null, 2);
  } catch (e) {
    raw = String(raw);
  }
}

const summaryText = raw.trim() || '⚠️ Empty summary received from API';
const filename = `session-summary-${sessionId}.txt`;

let buffer;
try {
  buffer = Buffer.from(summaryText, 'utf8');
} catch (e) {
  buffer = Buffer.from('⚠️ Error creating buffer from summary text', 'utf8');
}

return [{
  json: { filename, sessionId },
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'text/plain',
      fileName: filename,
      fileExtension: 'txt'
    }
  }
}];

